"Centre de localisation":"Kituo cha eneo",
"Autoriser la localisation":"Ruhusu kutambua eneo",
"Cette autorisation permet à l'application d'utiliser la position GPS de votre appareil pour afficher votre position, activer le partage de localisation et les fonctions de sécurité que vous choisissez. Rien n'est partagé sans votre action.":"Ruhusa hii inaruhusu programu kutumia nafasi ya GPS ya kifaa chako ili kuonyesha mahali ulipo, kuwezesha kushiriki eneo na vipengele vya usalama unavyochagua. Hakuna kinachoshirikiwa bila hatua yako.",
