"Ton appareil n'arrive pas à déterminer sa position. Vérifie que le GPS est activé et que tu as du réseau, puis réessaie.":"Kifaa chako hakiwezi kubaini mahali kilipo. Hakikisha GPS imewashwa na una mtandao, kisha jaribu tena.",
"La position met trop de temps à arriver. Essaie à l'extérieur ou près d'une fenêtre.":"Mahali ulipo panachelewa kupatikana. Jaribu nje au karibu na dirisha.",
"Ce navigateur ne gère pas la géolocalisation. Essaie Chrome, Safari ou Firefox à jour.":"Kivinjari hiki hakiauni utambuzi wa mahali. Jaribu Chrome, Safari au Firefox ya toleo jipya.",
