"Une erreur est survenue. Réessaie.":"Hitilafu imetokea. Jaribu tena.",
"Action refusée : les règles Firestore du Centre de localisation ne sont pas encore publiées (ou pas à jour). Va dans la section « Vérifier ma configuration » (onglet Confidentialité).":"Kitendo kimekataliwa: sheria za Firestore za Kituo cha eneo bado hazijachapishwa (au hazijasasishwa). Nenda kwenye sehemu ya « Hakiki mipangilio yangu » (kichupo cha Faragha).",
