"MODE SOS ACTIF depuis {ago}":"HALI YA SOS IMEWASHWA tangu {ago}",
"DÉSACTIVER LE SOS":"ZIMA SOS",
"SOS activé.":"SOS imewashwa.",
"SOS désactivé.":"SOS imezimwa.",
"{name} a activé le mode urgence. Ouvre le Centre de localisation pour voir sa position.":"{name} amewasha hali ya dharura. Fungua Kituo cha eneo kuona mahali alipo.",
"SOS terminé":"SOS imeisha",
"{name} a désactivé le mode urgence.":"{name} amezima hali ya dharura.",
"Alertes SOS de mes proches":"Tahadhari za SOS za wapendwa wangu",
"Aucune alerte en cours.":"Hakuna tahadhari inayoendelea.",
"depuis {ago}":"tangu {ago}",
"Position introuvable pour l'instant : le SOS est actif et se mettra à jour dès qu'une position arrive.":"Mahali hapajapatikana kwa sasa: SOS imewashwa na itasasishwa mara tu mahali patakapopatikana.",
"en attente":"inasubiri",
"Invitations reçues":"Mialiko iliyopokelewa",
"Aucun contact d'urgence.":"Hakuna mtu wa dharura.",
"{name} veut t'ajouter comme contact d'urgence.":"{name} anataka kukuongeza kama mtu wa dharura.",
"{name} souhaite t'ajouter comme contact d'urgence.":"{name} angependa kukuongeza kama mtu wa dharura.",
"Invitation envoyée.":"Mwaliko umetumwa.",
"Mes appareils":"Vifaa vyangu",
"Cet appareil":"Kifaa hiki",
"Hors ligne":"Nje ya mtandao",
"Suivre cet appareil":"Fuatilia kifaa hiki",
"Met à jour la dernière position de cet appareil quand l'application est ouverte, pour pouvoir le retrouver plus tard.":"Husasisha mahali pa mwisho pa kifaa hiki programu inapofunguliwa, ili uweze kukipata baadaye.",
"Demander une actualisation":"Omba usasishaji",
"Demande envoyée. Elle n'aboutit que si l'appareil a l'application ouverte avec le suivi activé.":"Ombi limetumwa. Linafanikiwa tu ikiwa kifaa kina programu iliyofunguliwa na ufuatiliaji umewashwa.",
"Voir sur la carte":"Tazama kwenye ramani",
"Aucun appareil enregistré. Active « Suivre cet appareil » sur chacun de tes appareils.":"Hakuna kifaa kilichosajiliwa. Washa « Fuatilia kifaa hiki » kwenye kila kifaa chako.",
"Limite technique : un navigateur ne peut pas être réveillé à distance. La dernière position affichée est celle reçue quand l'application était ouverte.":"Kikwazo cha kiufundi: kivinjari hakiwezi kuamshwa kwa mbali. Mahali pa mwisho panapoonyeshwa ni pale palipopokelewa programu ilipokuwa imefunguliwa.",
"Aucune position reçue.":"Hakuna mahali palipopokelewa.",
"Nom de l'appareil":"Jina la kifaa",
"Dernière activité : {ago}":"Shughuli ya mwisho: {ago}",
"Historique de mes positions":"Historia ya maeneo yangu",
"L'historique est désactivé. Tu peux l'activer dans Confidentialité.":"Historia imezimwa. Unaweza kuiwasha katika Faragha.",
"Aucune position enregistrée.":"Hakuna mahali palipohifadhiwa.",
"Effacer mon historique":"Futa historia yangu",
"Historique effacé.":"Historia imefutwa.",
"Une position toutes les {n} min au plus, seulement si tu as bougé d'au moins {m} m. Supprimée après {d} jours.":"Mahali pamoja kila baada ya dakika {n} kwa upeo, tu ikiwa umesogea angalau mita {m}. Hufutwa baada ya siku {d}.",
"Ce qui est collecté et pourquoi":"Kinachokusanywa na kwa nini",
"Ta position GPS : uniquement pour l'afficher sur la carte quand ce centre est ouvert. Rien n'est envoyé à nos serveurs tant que tu ne partages pas, n'actives pas le SOS, le suivi d'appareil ou l'historique.":"Mahali pako pa GPS: ni kwa ajili ya kukuonyesha kwenye ramani kituo hiki kikiwa wazi tu. Hakuna kinachotumwa kwa seva zetu hadi ushiriki, uwashe SOS, ufuatiliaji wa kifaa au historia.",
"Partage : ta dernière position est visible uniquement par les personnes que tu choisis, pendant la durée choisie. Tu peux arrêter à tout moment.":"Kushiriki: mahali pako pa mwisho panaonekana tu kwa watu unaowachagua, kwa muda uliochagua. Unaweza kusitisha wakati wowote.",
"SOS : position et heure partagées avec tes contacts d'urgence qui ont accepté, tant que le SOS est actif.":"SOS: mahali na saa vinashirikiwa na watu wako wa dharura waliokubali, mradi SOS imewashwa.",
"Appareil : dernière position, heure et niveau de batterie (si disponible), visibles par toi seul.":"Kifaa: mahali pa mwisho, saa na kiwango cha betri (ikiwa kinapatikana), vinaonekana kwako peke yako.",
"Historique : désactivé par défaut, visible par toi seul, positions espacées et supprimées automatiquement.":"Historia: imezimwa kwa chaguo-msingi, inaonekana kwako peke yako, maeneo yametenganishwa kwa muda na hufutwa kiotomatiki.",
"Adresse et carte : les coordonnées sont envoyées à OpenStreetMap (Nominatim) pour afficher l'adresse, et le fond de carte vient d'OpenStreetMap.":"Anwani na ramani: viwianishi hutumwa kwa OpenStreetMap (Nominatim) ili kuonyesha anwani, na mandharinyuma ya ramani yanatoka OpenStreetMap.",
"Enregistrer un historique":"Hifadhi historia",
"Supprimer toutes mes données de localisation":"Futa data yangu yote ya eneo",
"Supprimer définitivement ton historique, tes appareils, tes partages, tes contacts d'urgence et ta session SOS ?":"Kufuta kabisa historia yako, vifaa vyako, ushiriki wako, watu wako wa dharura na kipindi chako cha SOS?",
"Données de localisation supprimées.":"Data ya eneo imefutwa.",
