"Rejoins l'annuaire de localisation":"Jiunge na orodha ya eneo",
"Pour retrouver tes proches en un clic (et qu'ils te retrouvent), enregistre ton numéro ou ton email. Ils ne sont jamais affichés : ils servent seulement à te retrouver quand quelqu'un les tape.":"Ili kuwapata wapendwa wako kwa mbofyo mmoja (nao wakupate), hifadhi nambari yako ya simu au barua pepe. Hazionyeshwi kamwe: hutumika tu kukupata mtu anapoziandika.",
"Cherche un proche par nom, email ou numéro":"Tafuta mpendwa kwa jina, barua pepe au nambari",
"Touche « Localiser » : il reçoit ta demande":"Gusa « Tafuta mahali »: atapokea ombi lako",
"Il accepte (ou supprime) et choisit la durée":"Anakubali (au anafuta) na kuchagua muda",
"Renseigne au moins un numéro ou un email valide.":"Weka angalau nambari moja ya simu au barua pepe halali.",
"J'accepte d'apparaître dans l'annuaire (nom + photo). Personne ne voit ma position sans mon accord.":"Nakubali kuonekana kwenye orodha (jina + picha). Hakuna anayeona mahali nilipo bila ridhaa yangu.",
"Coche la case pour continuer.":"Weka alama kwenye kisanduku ili kuendelea.",
"Enregistrer et continuer":"Hifadhi na uendelee",
"Modifier mes coordonnées":"Badilisha taarifa zangu",
"Ce numéro ou cet email est déjà associé à un autre compte.":"Nambari hii au barua pepe hii tayari imeunganishwa na akaunti nyingine.",
"C'est fait, tu es dans l'annuaire.":"Tayari, uko kwenye orodha.",
"Retrouver un proche":"Mtafute mpendwa",
"Nom, @utilisateur, email ou numéro":"Jina, @mtumiaji, barua pepe au nambari",
"Membres de l'annuaire":"Wanachama wa orodha",
"Personne trouvé. Vérifie l'orthographe, ou invite-le ci-dessous.":"Hakuna aliyepatikana. Hakiki tahajia, au mwalike hapa chini.",
"Partager la mienne":"Shiriki yangu",
"Ajouter un contact d'urgence":"Ongeza mtu wa dharura",
"Il doit accepter ton invitation pour recevoir tes alertes SOS.":"Lazima akubali mwaliko wako ili apokee tahadhari zako za SOS.",
"Voit ta position":"Anaona mahali ulipo",
