"Veut voir ta position":"Anataka kuona mahali ulipo",
"Il n'est pas encore sur Coeurnoh ?":"Bado hayuko kwenye Coeurnoh?",
"Inviter un proche":"Alika mtu wa karibu",
"Rejoins-moi sur Coeurnoh pour partager notre position en toute sécurité : {url}":"Njoo Coeurnoh tushiriki mahali tulipo kwa usalama: {url}",
"Partager ma position avec {name}":"Shiriki mahali nilipo na {name}",
"Accepter la demande de {name}":"Kubali ombi la {name}",
"Pendant combien de temps {name} peut-il voir ta position ? Tu pourras arrêter à tout moment.":"{name} anaweza kuona mahali ulipo kwa muda gani? Utaweza kusimamisha wakati wowote.",
"Annuler la demande":"Ghairi ombi",
"Mon profil dans l'annuaire":"Wasifu wangu kwenye saraka",
"Tu ne seras plus retrouvable par nom, email ou numéro. Tes partages en cours ne sont pas modifiés.":"Hutaweza tena kupatikana kwa jina, barua pepe au namba. Ushirikishaji unaoendelea haubadiliki.",
"Tu as quitté l'annuaire.":"Umeondoka kwenye saraka.",
"Annuaire : seuls ton nom, ta photo et ton @utilisateur sont visibles par les membres inscrits. Ton email et ton numéro ne sont jamais affichés ; seule une empreinte chiffrée sert à te retrouver.":"Saraka: ni jina lako, picha yako na @mtumiaji pekee vinavyoonekana kwa wanachama waliojisajili. Barua pepe na namba yako hazionyeshwi kamwe; ni alama iliyosimbwa pekee inayotumika kukupata.",
"Rejoins l'annuaire pour partager ta position en un clic avec tes proches.":"Jiunge na saraka ili ushiriki mahali ulipo kwa mguso mmoja na wapendwa wako.",
"Demande acceptée":"Ombi limekubaliwa",
"{name} a accepté ta demande : tu peux voir sa position.":"{name} amekubali ombi lako: unaweza kuona mahali alipo.",
"Demande refusée":"Ombi limekataliwa",
"{name} a refusé ta demande de localisation.":"{name} amekataa ombi lako la kumpata mahali alipo.",
"Partage arrêté":"Ushirikishaji umesimamishwa",
"{name} a arrêté de partager sa position avec toi.":"{name} ameacha kushiriki mahali alipo nawe.",
"Contact d'urgence accepté":"Mwasiliani wa dharura amekubali",
"{name} a accepté d'être ton contact d'urgence.":"{name} amekubali kuwa mwasiliani wako wa dharura.",
"Et quand l'application est fermée ?":"Na ikiwa programu imefungwa?",
"Bloquée par le site":"Imezuiwa na tovuti",
"La localisation est bloquée par la configuration du site. Si tu administres le site, vérifie que vercel.json (Permissions-Policy : geolocation=(self)) est bien déployé.":"Eneo limezuiwa na mipangilio ya tovuti. Ikiwa unasimamia tovuti, hakikisha vercel.json (Permissions-Policy: geolocation=(self)) imewekwa kwenye seva ipasavyo.",
"La carte est bloquée par la configuration de sécurité du site. Si tu administres le site, vérifie que vercel.json est bien déployé.":"Ramani imezuiwa na mipangilio ya usalama ya tovuti. Ikiwa unasimamia tovuti, hakikisha vercel.json imewekwa kwenye seva ipasavyo.",
"Mon lien de localisation":"Kiungo changu cha mahali",
"Crée un lien et envoie-le sur WhatsApp, Messenger, Facebook, TikTok, Instagram… La personne qui l'ouvre se connecte à Coeurnoh Universe, puis voit ta position sur la carte.":"Tengeneza kiungo na ukitume kwenye WhatsApp, Messenger, Facebook, TikTok, Instagram… Anayekifungua huingia kwenye Coeurnoh Universe, kisha huona mahali ulipo kwenye ramani.",
"Toute personne qui ouvre ce lien et se connecte verra ta position jusqu'à l'expiration. Tu peux le désactiver à tout moment.":"Yeyote anayefungua kiungo hiki na kuingia ataona mahali ulipo hadi kiungo kikome kutumika. Unaweza kukizima wakati wowote.",
"Créer mon lien":"Tengeneza kiungo changu",
"Lien créé. Choisis comment l'envoyer.":"Kiungo kimetengenezwa. Chagua jinsi ya kukituma.",
"Mes liens actifs":"Viungo vyangu vinavyotumika",
"Jusqu'à désactivation":"Hadi kizimwe",
"{n} connectée(s)":"{n} walioingia",
