"TikTok / Instagram : touche « Autres apps » ou copie le lien, puis colle-le dans ton message ou ta bio.":"TikTok / Instagram: gusa « Programu nyingine » au nakili kiungo, kisha kibandike kwenye ujumbe wako au bio yako.",
"{name} partage sa position avec toi sur Coeurnoh Universe. Ouvre le lien et connecte-toi pour la voir :":"{name} anashiriki mahali alipo nawe kwenye Coeurnoh Universe. Fungua kiungo na uingie ili kuona:",
"{name} partage sa position avec toi":"{name} anashiriki mahali alipo nawe",
"Tu verras sa position sur la carte jusqu'à {until}. Tu pourras quitter à tout moment.":"Utaona mahali alipo kwenye ramani hadi {until}. Utaweza kuondoka wakati wowote.",
"Voir sa position":"Ona mahali alipo",
"Position partagée avec toi.":"Mahali pameshirikiwa nawe.",
"Lien invalide ou désactivé.":"Kiungo si sahihi au kimezimwa.",
"Ce lien a expiré.":"Kiungo hiki kimekwisha muda.",
