"Plein écran":"Skrini nzima",
"Quitter le plein écran":"Toka kwenye skrini nzima",
"L'annuaire est inaccessible. Les règles Firestore du Centre de localisation ne sont probablement pas encore publiées. Ouvre « Vérifier ma configuration » (onglet Confidentialité).":"Saraka haipatikani. Huenda kanuni za Firestore za Kituo cha Mahali bado hazijachapishwa. Fungua « Hakiki mipangilio yangu » (kichupo cha Faragha).",
"Tu es l'un des premiers membres ! Invite tes proches, ou crée ton lien de localisation juste en dessous.":"Wewe ni mmoja wa wanachama wa kwanza! Alika wapendwa wako, au tengeneza kiungo chako cha mahali hapo chini.",
