"Autorisation GPS du site":"Ruhusa ya GPS ya tovuti",
"Permission GPS du téléphone":"Ruhusa ya GPS ya simu",
"Règles Firestore":"Kanuni za Firestore",
"Le serveur envoie encore l'ancienne configuration : le fichier vercel.json n'est pas déployé (GitHub → Vercel, attends le statut « Ready »).":"Seva bado inatuma mipangilio ya zamani: faili ya vercel.json haijawekwa (GitHub → Vercel, subiri hali « Ready »).",
"Le serveur est à jour mais cet appareil garde une ancienne version : touche « Réparer et recharger ».":"Seva imesasishwa lakini kifaa hiki bado kina toleo la zamani: gusa « Rekebisha na upakie upya ».",
"Règles non publiées ou incomplètes : Firebase Console ▸ Firestore ▸ Règles ▸ coller le fichier complet ▸ Publier.":"Kanuni hazijachapishwa au hazijakamilika: Firebase Console ▸ Firestore ▸ Kanuni ▸ bandika faili nzima ▸ Chapisha.",
"Impossible de charger la carte (réseau ou blocage).":"Imeshindwa kupakia ramani (mtandao au kizuizi).",
"Pas encore demandée : touche « Activer ma position » dans l'onglet Position.":"Bado haijaombwa: gusa « Washa mahali nilipo » kwenye kichupo cha Mahali ulipo.",
"Notifications bloquées : autorise-les dans les réglages du navigateur pour recevoir les alertes.":"Arifa zimezuiwa: ziruhusu kwenye mipangilio ya kivinjari ili upokee tahadhari.",
"Pas encore autorisées : active-les pour recevoir les alertes même application fermée.":"Bado hazijaruhusiwa: ziwashe ili upokee tahadhari hata programu ikiwa imefungwa.",
"Mise à jour de l'application…":"Inasasisha programu…",
"Dépend de l'étape « Autorisation GPS du site » : corrige-la d'abord (bouton Réparer), puis relance la vérification.":"Inategemea hatua ya « Ruhusa ya GPS ya tovuti »: irekebishe kwanza (kitufe cha Rekebisha), kisha anzisha ukaguzi upya.",
"Échange mutuel : partager aussi ma position":"Kubadilishana: shiriki pia mahali nilipo",
"Quand je touche « Localiser », je partage aussi ma position avec cette personne (durée au choix) : vous vous voyez chacun sur la carte.":"Ninapogusa « Tafuta mahali », ninashiriki pia mahali nilipo na mtu huyu (kwa muda utakaochagua): mnaonana nyote kwenye ramani.",
"Échanger nos positions avec {name}":"Badilishana mahali ulipo na {name}",
