"Enregistre ton numéro ou ton email pour apparaître dans la liste et être retrouvé. Tu peux déjà chercher et envoyer des demandes ci-dessous.":"Hifadhi namba yako au barua pepe yako ili uonekane kwenye orodha na upatikane. Tayari unaweza kutafuta na kutuma maombi hapa chini.",
